-- Rifts World Book 2: Atlantis - rune weapons (printed 126-131): 14 new rows.
-- The catalog's estimated Lesser Rune Weapon row is given the book's price by
-- ~007-atlantis-lesser-rune-weapon-price.sql, which has to sort after the
-- estimate scripts.
-- See apps/character-creator/docs/surveys/atlantis.md.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-atlantis-rune-weapons.sql
--
-- READ FROM A SCAN. Extracted by book-extract-worker from printed 126-133.
-- Printed 128 sets the greater weapons, the Soul Drinker and the Holy Weapons
-- in interleaved columns; it was read whole. Printed 130's OCR lost four bold
-- headings (Crystal Fire Rod, Dragon Thunderer, The Enslaver, The Impaler),
-- recovered from a 200 dpi render.
--
-- ROWS: the four generic grades the book prices (greater 20-80 million, soul
-- drinker 30-120 million, holy simple 0.5-5 million and greater 2-12 million,
-- greatest 6D4x10 million) and the nine named greatest weapons. Generic grades
-- are 'magic', as the existing lesser-rune-weapon row is; named weapons are
-- 'weapon', as Underseas' rune weapons are, except The Enslaver, a statue-like
-- device. Where a range is printed, cost is its low end and cost_note the
-- range. The named greatest weapons print no individual price, so cost is NULL
-- and cost_note gives the grade's; three are never less than 500 million.
--
-- LESSER RUNE WEAPON already existed (`lesser-rune-weapon`, estimated at
-- 250,000); printed 128 prices it at four to sixteen million credits. See
-- ~007-atlantis-lesser-rune-weapon-price.sql.
--
-- NOT HERE: the Splugorth rune statues (printed 132-133), which print combat
-- stats and no price and are creatures, not gear (survey batch 9).

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('greater-rune-weapon', 'Greater Rune Weapon', 'rifts', 'magic', NULL, 20000000, '20 to 80 million credits, sometimes more.', 'No less than 4D6 M.D.', 1, 'melee', NULL, 'melee', NULL, NULL, NULL, 'A rune weapon with the eight standard abilities plus one or two greater powers: cast four offensive elemental spells a day of one element, levels 1-6, as a sixth level warlock; or healing (heal wounds 2D6 hit points and 2D6 S.D.C., or 2D6 M.D.C., six times a day; remove curse 56% four times a day; turn 4D6 dead 55% and animate and command 2D6 dead 64%, each four times a day for four hours); or psionics (every sensitive and physical power and three super psionic powers, 3D6x10 I.S.P. at sixth level proficiency). Many rune weapons are also cursed. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.128'),
('soul-drinker-rune-weapon', 'Soul Drinker Rune Weapon', 'rifts', 'magic', NULL, 30000000, '30 to 120 million credits, sometimes more.', 'No less than 4D6 M.D.', 1, 'melee', NULL, 'melee', NULL, NULL, NULL, 'The most powerful of the greater rune weapons, typically a blade: the eight standard abilities, two greater powers, and the ability to drink souls. The weapon must first draw the victim''s blood; most are limited to 1D6 souls a day, and a devoured victim is lost forever. The victim saves vs magic on 14 or higher; a successful save means double damage instead (triple to a mega-damage creature). Seventy percent of all rune weapons are rune swords. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.128'),
('simple-holy-weapon', 'Holy Weapon (Simple)', 'rifts', 'magic', NULL, 500000, '500,000 to five million credits. Not generally sold: most are given to knights, paladins and other champions of good, and those on the market were stolen, pawned or found.', 'No less than 2D6+6 (M.D. on mega-damage worlds, S.D.C. elsewhere)', 1, 'melee', NULL, 'melee', NULL, NULL, NULL, 'A rune weapon made by or for the forces of good against supernatural evil, usually a sword or staff. It glows faint white, yellow, red or blue, registers as magic, is indestructible and has the lesser rune weapon abilities 3, 6, 7 and 8, but no intelligence, personality or telepathy. A simple holy weapon has TWO of: remove curse 50% (once per person); turn 4D6 dead 80%; healing touch 2D6 S.D.C. and hit points or 2D6 M.D.C., six times a day; +2D6 damage; monster slayer (double damage to supernatural beings and creatures of magic, including dragons); +1 save vs magic and +2 vs horror factor; sense evil in a 20 foot (6.1 m) radius; expel devils and demons (89% against lesser, 44% against greater); circle of protection for five minutes per level of the wielder.', 'Rifts World Book 2: Atlantis p.128'),
('greater-holy-weapon', 'Holy Weapon (Greater)', 'rifts', 'magic', NULL, 2000000, 'Two to 12 million credits or more. Not generally sold; see Holy Weapon (Simple).', 'No less than 2D6+6 (M.D. on mega-damage worlds, S.D.C. elsewhere)', 1, 'melee', NULL, 'melee', NULL, NULL, NULL, 'As the simple holy weapon, but with FOUR of the holy weapon special abilities instead of two (remove curse, turn dead, healing touch, damage bonus, monster slayer, magic bonus, sense evil, expel devils and demons, circle of protection).', 'Rifts World Book 2: Atlantis p.128'),
('greatest-rune-weapon', 'Greatest Rune Weapon', 'rifts', 'magic', NULL, 60000000, 'Typically 6D4x10 million credits, and two or three times that depending on the weapon and the seller (printed 129).', 'No less than 4D6 M.D.', 1, 'melee', NULL, 'melee', NULL, NULL, NULL, 'The eight standard abilities plus two of: elemental magic, healing or psionics as a greater rune weapon; drinking souls; six spells of levels 6-11, three times a day, at 1D4+7th level; curses (luck curse, minor curse, phobia curse, compulsion, remove curse 54%) three times a day at tenth level; dimensional travel (teleport lesser and superior, mystic portal, time hole, sanctum) twice a day at tenth level; a double dragon-head breath weapon (fire blast 1D6x10 M.D. or force blast 2D4x10 M.D. to 1000 ft/305 m, or lightning 1D6x10 M.D. to 2000 ft/610 m, double damage to vampires and alien intelligences); or animated flight (thrown 1000 ft/305 m and returns; animated it has three attacks per melee, +4 to strike and parry, +2 on initiative, but cannot drink souls or cast spells). The rarest have three. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.129'),
('call-staff', 'Call Staff', 'rifts', 'weapon', NULL, NULL, 'A greatest rune weapon: typically 6D4x10 million credits (printed 129).', '5D6 M.D. physical blows; the detachable bladed tip flies as a guided missile for 1D4x10 M.D.', 1, 'melee; tip thrown as a guided missile', NULL, 'melee', NULL, NULL, NULL, 'Casts calling, commune with spirits, magic pigeon, compulsion, control and enslave entities, repel animals and turn dead three times a day, and every summoning spell (each once per 48 hours), all as an eighth level sorcerer. The bladed tip detaches and flies as a guided missile, +5 to strike a moving target, at most twice per melee round, and returns. A greatest rune weapon (printed 129): the eight standard abilities plus two greater or special abilities, usually made from a god, godling or demon lord. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.129'),
('crystal-fire-rod', 'Crystal Fire Rod', 'rifts', 'weapon', NULL, NULL, 'A greatest rune weapon: typically 6D4x10 million credits (printed 129).', '5D6 M.D. physical blows; laser beam 5D6 M.D.', 1, 'laser 2000 feet (610 m)', NULL, NULL, NULL, NULL, NULL, 'A crystal mace-like weapon powered by a fire elemental. Casts blinding flash, globe of daylight, cloud of smoke, wall of flame, circle of flame, fire bolt, fire ball, ignite fire, fuel flame and impervious to fire, three times a day as a twelfth level warlock (optionally two fire warlock spells per level instead, 14 in all). Fires a laser beam, one per hand to hand attack; can parry laser blasts at -2; radiates daylight in a 50 ft (15 m) radius and heat to 80 degrees F over 10 feet. A greatest rune weapon (printed 129): the eight standard abilities plus two greater or special abilities, usually made from a god, godling or demon lord. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.129'),
('dragon-rod', 'Dragon Rod', 'rifts', 'weapon', NULL, NULL, 'A greatest rune weapon: typically 6D4x10 million credits (printed 129).', '4D6 M.D. as a blunt weapon; energy bolt 2D6 M.D.; fire ball 1D4x10+8 M.D.; lightning blast 2D4x10 M.D.; wind rush 1D4 M.D.', 1, 'energy bolt and fire ball 1000 feet (305 m); lightning 2000 feet (610 m); wind rush 240 feet (73 m)', NULL, NULL, NULL, NULL, NULL, 'A gun-shaped rod whose barrel is a dragon neck and head, with no moving parts. Casts circle of flame, fly, magic pigeon, and metamorphosis human and animal three times a day as a twelfth level sorcerer. Unlimited mouth attacks, one per hand to hand attack: energy bolt, fire ball, lightning blast, carpet of adhesion and magic net (as a twelfth level sorcerer), and wind rush at double range. A greatest rune weapon (printed 129): the eight standard abilities plus two greater or special abilities, usually made from a god, godling or demon lord. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.129'),
('dragon-thunderer', 'Dragon Thunderer', 'rifts', 'weapon', NULL, NULL, 'A greatest rune weapon: typically 6D4x10 million credits (printed 129).', '1D4x10 M.D. plus a thunderclap on each strike', 1, 'melee; thrown 300 feet (91.5 m) and returns', NULL, 'melee', NULL, NULL, NULL, 'An axe, mace or war hammer with a dragon head. Casts invulnerability, levitation, summon rain and calm storms three times a day as an eighth level sorcerer. Each strike releases a thunderclap; thrown, it magically returns. A greatest rune weapon (printed 129): the eight standard abilities plus two greater or special abilities, usually made from a god, godling or demon lord. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.130'),
('the-enslaver', 'The Enslaver', 'rifts', 'magic', NULL, NULL, 'A greatest rune weapon: typically 6D4x10 million credits (printed 129).', 'Psi-sword up to 8D6 M.D.; mind bolt', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A rune device shaped like an insect statue. Casts trance, compulsion, dominance, fear and mask of deceit three times a day. Psionics with 2D6x10+100 I.S.P.: empathy, telepathy, sense evil, sense magic, see the invisible, sixth sense, bio-manipulation, empathic transmission, hypnotic suggestion, mentally possess others, mind bolt, mind bond, mind wipe, mind block auto-defense, psi-shield (80 M.D.C.) and psi-sword (up to 8D6 M.D.). A greatest rune weapon (printed 129): the eight standard abilities plus two greater or special abilities, usually made from a god, godling or demon lord. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.130'),
('necronstaff', 'Necronstaff', 'rifts', 'weapon', NULL, 500000000, 'Never less than 500 million credits (printed 129).', '6D6 M.D. physical blows, double to vampires, ghouls, zombies and animated dead; the skull breathes fire 1D4x10 M.D., or a toxic cloud 4D6 M.D., or bites 4D6 M.D.', 1, 'melee; fire breath 60 feet (18.3 m)', NULL, 'melee', NULL, NULL, NULL, 'A demonic-looking staff that drinks souls. Casts animate and control dead, turn dead, sickness, spoil, minor curse, fear, death trance, shadow meld and fire ball three times a day as an eighth level sorcerer, and summons 1D4 shadow beasts once per 72 hours for eight hours. Its skull has ONE of: breathe fire (1D4x10 M.D., 60 ft/18.3 m); a toxic gas cloud (4D6 M.D., -1 to strike, parry and dodge, 20 ft/6 m radius); a cloud of darkness (20 ft/6 m radius; those inside lose half their melee actions and their sense of direction); or a bite (4D6 M.D. and 1D4 melee rounds of weakness: the victim loses one attack and is -2 to strike, parry and dodge). A greatest rune weapon (printed 129): the eight standard abilities plus two greater or special abilities, usually made from a god, godling or demon lord. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.130'),
('the-impaler', 'The Impaler', 'rifts', 'weapon', NULL, NULL, 'A greatest rune weapon: typically 6D4x10 million credits (printed 129).', '1D6x10 M.D. physical blows; each spiked finger 2D4+2 M.D., all four at one target 1D4x10 M.D.', 1, 'melee; fired spikes', NULL, 'melee', NULL, NULL, NULL, 'Usually a sword, sometimes a spear or pole-arm, that drinks souls. Four spiked finger appendages fire as projectiles once or twice per melee round (+2 to strike when all four fire at one target). It can animate and crawl like a spider (speed 12, climb 80%), grab and carry small items, with two attacks or four non-combat actions per melee. A greatest rune weapon (printed 129): the eight standard abilities plus two greater or special abilities, usually made from a god, godling or demon lord. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.130'),
('sword-of-atlantis', 'Sword of Atlantis', 'rifts', 'weapon', NULL, 500000000, 'Never less than 500 million credits (printed 129). The gem-encrusted hilt alone is worth 1D6 million credits.', '1D6x10 M.D. physical blows, double to vampires and alien intelligences (the Splugorth included); double dragon-head breath: fire blast 1D6x10 M.D., force blast 2D4x10 M.D. or lightning 1D6x10 M.D.', 1, 'melee; thrown 1000 feet (305 m) and returns; breath 1000 feet (305 m), lightning 2000 feet (610 m)', NULL, 'melee', NULL, NULL, NULL, 'An ornate double dragon-headed sword with a winged, gem-encrusted hilt that drinks souls. Casts turn dead, heal wounds, fear, globe of daylight, invisibility (superior), protection (superior), mystic portal and close rift three times a day as a twelfth level sorcerer. It flies when thrown and returns, and can fully animate (three attacks per melee, +4 to strike and parry, +2 on initiative, fighting up to 200 ft/61 m from its owner, but cannot drink souls or cast spells while animated). Its breath weapon is ONE of the three, double damage to vampires and alien intelligences. A greatest rune weapon (printed 129): the eight standard abilities plus two greater or special abilities, usually made from a god, godling or demon lord. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.131'),
('sword-of-life', 'Sword of Life', 'rifts', 'weapon', NULL, 500000000, 'Never less than 500 million credits (printed 129).', '4D6 M.D. to most creatures; double to vampires and undead, ghouls, zombies, mummies, demon lords and gods of death, and all animated dead', 1, 'melee', NULL, 'melee', NULL, NULL, NULL, 'An indestructible silver sword with an angelic winged-figure hilt. It has the healing abilities of a greater rune weapon, casts invulnerability, negate magic, cure illness, purification, stone to flesh and remove curse three times a day as an eleventh level sorcerer, and animates, flies and fights like the Sword of Atlantis. A greatest rune weapon (printed 129): the eight standard abilities plus two greater or special abilities, usually made from a god, godling or demon lord. Every rune weapon has the eight standard abilities (printed 127-128): an independent personality of average to high I.Q.; limited telepathy with its owner; it is indestructible and never dulls; it is black, dark grey, blue-grey or dark red metal or stone lined with runes; it inflicts no less than 4D6 M.D. (4D6 S.D.C. on S.D.C. worlds) and can parry energy blasts at -6; it links to a wielder after six months of constant contact and senses its owner within 4 miles (6.4 km); +1 to all saving throws; and only a wielder of compatible alignment can use it - anyone else takes 1D8 S.D.C., or 3D6 M.D. if a mega-damage creature, each time he touches it. Rune weapons hold the trapped life essence of a powerful being; only the Splugorth still make them.', 'Rifts World Book 2: Atlantis p.131');



-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'the 14 rune weapon rows are in' AS assertion, count(*) AS got, 14 AS want
  FROM gear WHERE slug IN ('greater-rune-weapon', 'soul-drinker-rune-weapon', 'simple-holy-weapon', 'greater-holy-weapon', 'greatest-rune-weapon', 'call-staff', 'crystal-fire-rod', 'dragon-rod', 'dragon-thunderer', 'the-enslaver', 'necronstaff', 'the-impaler', 'sword-of-atlantis', 'sword-of-life') AND source_book LIKE 'Rifts World Book 2: Atlantis p.%';

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-atlantis-rune-weapons.sql');
